INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (1, 'POP_RESIDENTE', 'População Residente', 'Total de pessoas residentes na poligonal oficial do território segundo o Universo do Censo Demográfico 2022.', 'habitantes', 'Demográfica', 'Dado observado', 'Bairro / Setor / Município', 2022, 'IBGE Censo 2022 Básico: V0001', 'V0001 (valor direto publicado pelo IBGE)', 'Contagem direta da população residente na data de referência do Censo 2022 dentro dos limites oficiais da Lei Municipal nº 9.278/2017.', 'Difere ligeiramente do recorte de Favelas e Comunidades Urbanas (FCU), pois a FCU Beiru/Tancredo Neves (38.871 hab.) ultrapassa trechos de borda da poligonal do bairro oficial (38.329 hab.), enquanto em Pernambués a FCU (35.110 hab.) corresponde a 66,8% do bairro oficial (52.564 hab.).');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (2, 'DOM_OCUPADOS', 'Domicílios Particulares Permanentes Ocupados (DPPO)', 'Total de domicílios particulares permanentes ocupados no território.', 'domicílios', 'Demográfica', 'Dado observado', 'Bairro / Setor / Município', 2022, 'IBGE Censo 2022 Domicílios 1: V00001 (e Básico V0002 / V0007)', 'V00001 (valor direto publicado pelo IBGE)', 'Contabiliza as unidades domiciliares permanentes com moradores na data de referência, servindo de denominador oficial para taxas de saneamento e tipologia habitacional.', 'Não detalha a qualidade das instalações elétricas internas nem a subdivisão informal de medidores (''gatos'' ou relógios compartilhados em casas de laje).');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (3, 'DENSIDADE_DEMOGRAFICA', 'Densidade Demográfica', 'Relação entre a população residente total e a área territorial oficial em quilômetros quadrados.', 'hab/km²', 'Demográfica', 'Indicador derivado', 'Bairro / Setor / Município', 2022, 'IBGE Censo 2022 Básico: V0001 e AREA_KM2', 'V0001 / AREA_KM2', 'Razão direta entre moradores residentes (V0001) e área da poligonal oficial (AREA_KM2) calculada pelo IBGE na malha CD2022.', 'Trata a área do bairro como homogênea; áreas verdes ou vias expressas nas bordas de Pernambués diluem a densidade média em relação ao núcleo hiperadensado das encostas.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (4, 'MEDIA_MORADORES_DOM', 'Média de Moradores por Domicílio Ocupado', 'Número médio de moradores por domicílio particular ocupado no território.', 'moradores/dom', 'Demográfica', 'Dado observado', 'Bairro / Setor / Município', 2022, 'IBGE Censo 2022 Básico: V0005', 'V0005 (Publicado pelo IBGE: Total de moradores / DPPO + DPIO)', 'Quociente oficial publicado pelo IBGE entre moradores residentes em domicílios particulares ocupados e o total desses domicílios.', 'A média esconde os extremos de adensamento familiar (domicílios com 6 ou mais pessoas), razão pela qual complementamos com o indicador de adensamento elevado.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (5, 'RAZAO_DEPENDENCIA_ETARIA', 'Razão de Dependência Demográfica', 'Proporção de pessoas em faixas etárias potencialmente dependentes (0 a 14 anos e 60 anos ou mais) em relação à população em idade ativa (15 a 59 anos).', '%', 'Demográfica', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Demografia: V01031 a V01041', '((V01031 + V01032 + V01033 + V01040 + V01041) / (V01034 + V01035 + V01036 + V01037 + V01038 + V01039)) * 100', 'Soma dos contingentes infantis/juvenis (0-14 anos) e idosos (60+ anos) dividida pelo contingente adulto (15-59 anos).', 'Baseia-se exclusivamente em recortes etários, não capturando desemprego ou permanência prolongada no domicílio por cuidados domésticos (que eleva o consumo residencial diurno de energia).');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (6, 'PERC_POP_NEGRA', 'Proporção de População Negra (Preta e Parda)', 'Percentual da população residente autodeclarada preta ou parda segundo os critérios raciais do IBGE.', '%', 'Demográfica', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Cor ou Raça: V01318 (Preta), V01320 (Parda), V0001 (População)', '((V01318 + V01320) / V0001) * 100', 'Agregação das categorias censitárias Preta e Parda sobre o total populacional do território.', 'Evidencia a dimensão racial da segregação socioespacial em Salvador, mas deve ser cruzada com indicadores de renda e infraestrutura para análise interseccional.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (7, 'RENDA_MEDIA_RESP', 'Rendimento Nominal Médio Mensal do Responsável', 'Valor médio do rendimento nominal mensal das pessoas responsáveis pelo domicílio particular permanente ocupado.', 'R$', 'Econômica', 'Dado observado', 'Bairro / Setor / Município', 2022, 'IBGE Censo 2022 Rendimento do Responsável: V06004', 'V06004 (valor direto publicado pelo IBGE em R$ correntes de 2022)', 'Média aritmética dos rendimentos brutos nominais mensais dos responsáveis pelos domicílios particulares permanentes ocupados.', 'Sensível a valores extremos (outliers): em Pernambués, condomínios de classe média nas bordas elevam a média (R$ 2.316,25), embora a mediana seja idêntica à de Beiru/Tancredo Neves (R$ 1.212,00).');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (8, 'RENDA_MEDIANA_RESP', 'Rendimento Nominal Mediano Mensal do Responsável', 'Valor mediano (percentil 50%) do rendimento nominal mensal das pessoas responsáveis pelo domicílio.', 'R$', 'Econômica', 'Dado observado', 'Bairro / Setor / Município', 2022, 'IBGE Censo 2022 Rendimento do Responsável: V06006', 'V06006 (valor direto publicado pelo IBGE em R$ correntes de 2022)', 'Valor central que divide a distribuição de rendimentos dos responsáveis em duas partes iguais (50% ganham até esse valor).', 'Considera apenas o rendimento do responsável pelo domicílio (e não a renda domiciliar per capita completa com todos os moradores), mas comprova concentração de baixa renda (R$ 1.212 = 1 salário mínimo de 2022).');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (9, 'PERC_SETORES_BAIXA_RENDA', 'Concentração de Setores Censitários de Baixa Renda (≤ 1,5 SM)', 'Percentual dos setores censitários do bairro cujo rendimento médio do responsável é igual ou inferior a 1,5 salário mínimo de 2022 (R$ 1.818,00).', '%', 'Econômica', 'Indicador derivado', 'Bairro (agregado de Setores Censitários)', 2022, 'IBGE Censo 2022 Setores Renda: V06004 por CD_SETOR', '(Count(Setores com V06004 <= 1818.00) / Total_Setores_Bairro) * 100', 'Agregação espacial dos 72 setores de Beiru/Tancredo Neves e 100 setores de Pernambués para medir a extensão territorial da baixa renda.', 'Mede a concentração ecológica por setor censitário; famílias de baixa renda também podem residir em setores com média superior a 1,5 SM.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (10, 'TAXA_ALFABETIZACAO_15MAIS', 'Taxa de Alfabetização (15 anos ou mais)', 'Percentual da população residente de 15 anos ou mais de idade que sabe ler e escrever um bilhete simples.', '%', 'Social', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Alfabetização: V00900 (alfabetizados 15+) e V00901 (não alfabetizados 15+)', '(V00900 / (V00900 + V00901)) * 100', 'Razão entre pessoas de 15+ anos alfabetizadas e o total de moradores nessa faixa etária.', 'Não mede o analfabetismo funcional nem o grau de letramento digital/financeiro necessário para acessar tarifas sociais (como cadastro na TSEE ou leitura de faturas de energia).');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (11, 'IVS_GERAL_IPEA', 'Índice de Vulnerabilidade Social Geral (IVS - IPEA)', 'Índice sintético do IPEA (0 a 1) que mensura a exclusão e a insuficiência de ativos em Infraestrutura Urbana, Capital Humano e Renda e Trabalho.', 'índice (0 a 1)', 'Social', 'Dado observado', 'UDH / Município / UF (Escalas publicadas pelo IPEA)', 2022, 'IPEA Atlas da Vulnerabilidade Social: IVS Geral, IVS Infraestrutura, IVS Capital Humano, IVS Renda e Trabalho', '(IVS_Infraestrutura + IVS_Capital_Humano + IVS_Renda_Trabalho) / 3', 'Média aritmética dos três subíndices normalizados de 0 (menor vulnerabilidade) a 1 (maior vulnerabilidade). Valores acima de 0,400 indicam Alta Vulnerabilidade.', 'Cuidado metodológico essencial: na escala intramunicipal (UDHs), a última malha publicada pelo IPEA/FJP baseia-se no ciclo censitário de 2010; já as atualizações de 2021-2022 do IPEA via PNAD Contínua têm cobertura apenas estadual (UF Bahia = 0,255) e metropolitana.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (12, 'ACESSO_AGUA_REDE', 'Abastecimento de Água via Rede Geral', 'Percentual de domicílios particulares permanentes ocupados ligados à rede geral de distribuição de água.', '%', 'Habitacional', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Domicílios 2: V00111 e Domicílios 1: V00001', '(V00111 / V00001) * 100', 'Proporção de DPPO cuja forma principal de abastecimento de água é a rede geral de distribuição.', 'Mede a existência de conexão física à rede, mas não capta a intermitência do fornecimento (manobras de racionamento em áreas altas como cumeadas do Beiru, que exigem bombeamento elétrico residencial).');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (13, 'ESGOTO_REDE_ADEQUADO', 'Esgotamento Sanitário Adequado (Rede Geral ou Fossa Ligada)', 'Percentual de domicílios particulares permanentes ocupados com esgotamento sanitário via rede geral/pluvial ou fossa séptica ligada à rede.', '%', 'Habitacional', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Domicílios 2: V00309, V00310 e V00001', '((V00309 + V00310) / V00001) * 100', 'Soma dos DPPO atendidos por rede coletora geral/pluvial ou fossa séptica ligada à rede sobre o total de DPPO.', 'A agregação de rede geral e pluvial pelo questionário básico não distingue ligações clandestinas em galerias de águas pluviais de redes coletoras com tratamento secundário.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (14, 'COLETA_LIXO_DIRETA', 'Coleta de Lixo Direta (Porta a Porta)', 'Percentual de domicílios particulares permanentes ocupados cujo lixo é coletado diretamente no domicílio por serviço de limpeza.', '%', 'Habitacional', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Domicílios 2: V00397 e V00001', '(V00397 / V00001) * 100', 'Proporção de DPPO com coleta domiciliar direta (excluindo depósito em caçamba comunitária V00398).', 'Indicador crucial de morfologia urbana: embora a coleta total (direta + caçamba) supere 95%, apenas 29,19% em Beiru/Tancredo Neves e 40,83% em Pernambués têm coleta porta a porta devido à inacessibilidade viária de becos e escadarias.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (15, 'ADENSAMENTO_DOMICILIAR_6MAIS', 'Domicílios com Adensamento Elevado (6 ou mais moradores)', 'Percentual de domicílios particulares permanentes ocupados com 6 ou mais moradores residentes.', '%', 'Habitacional', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Domicílios 1: V00022, V00023, V00024, V00025, V00026 e V00001', '((V00022 + V00023 + V00024 + V00025 + V00026) / V00001) * 100', 'Soma dos domicílios ocupados com 6, 7, 8, 9 e 10+ moradores dividida pelo total de DPPO.', 'Não considera a área útil (m²) nem o número de dormitórios (divulgado apenas na Amostra), mas identifica famílias numerosas com maior pressão sobre o consumo elétrico básico (geladeira, banho quente, ventilação).');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (16, 'ENTORNO_ILUMINACAO_PUBLICA', 'Cobertura de Iluminação Pública no Entorno', 'Percentual de domicílios particulares permanentes ocupados localizados em faces de quadra com iluminação pública.', '%', 'Urbana', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Entorno Domicílios: V05012 e V05000', '(V05012 / V05000) * 100', 'Observação direta pelo recenseador da existência de ao menos um ponto de iluminação pública na face de quadra do domicílio.', 'Conforme destacado na orientação metodológica, iluminação pública na rua NÃO mede a continuidade, a regularidade contratual nem a qualidade do fornecimento elétrico residencial interno (DEC/FEC).');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (17, 'ENTORNO_PAVIMENTACAO', 'Vias Pavimentadas no Entorno Domiciliar', 'Percentual de domicílios localizados em faces de quadra com via pavimentada (asfalto, paralelepípedo, concreto).', '%', 'Urbana', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Entorno Domicílios: V05006 e V05000', '(V05006 / V05000) * 100', 'Proporção de DPPO em setores de entorno cuja face de quadra possui revestimento de pavimentação.', 'Inclui pavimentação de concreto em escadarias/becos de pedestres, não significando necessariamente acesso para veículos de manutenção da rede elétrica ou coleta direta.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (18, 'ENTORNO_CALCADA', 'Presença de Calçada / Passeio Público', 'Percentual de domicílios localizados em faces de quadra que possuem calçada ou passeio pavimentado.', '%', 'Urbana', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Entorno Domicílios: V05021 e V05000', '(V05021 / V05000) * 100', 'Razão entre domicílios em face com calçada (V05021) e o total de domicílios avaliados na pesquisa de entorno (V05000).', 'Evidencia forte déficit de urbanização: mais de 60% dos domicílios em Beiru/Tancredo Neves (39,46% com calçada) e Pernambués (38,57%) não possuem calçada padronizada.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (19, 'ENTORNO_ARBORIZACAO', 'Arborização Viária no Entorno (1 ou mais árvores)', 'Percentual de domicílios situados em faces de quadra com presença de arborização (1 a 2, 3 a 4, ou 5 ou mais árvores).', '%', 'Urbana', 'Indicador derivado', 'Bairro / Município', 2022, 'IBGE Censo 2022 Entorno Domicílios: V05031, V05032, V05033 e V05000', '((V05031 + V05032 + V05033) / V05000) * 100', 'Soma dos domicílios em faces com qualquer faixa de arborização dividida pelo universo do entorno (V05000). Complementarmente, V05030/V05000 mede o déficit arbóreo (74,37% sem árvores no Beiru vs 65,07% em Pernambués).', 'Contabiliza apenas árvores em áreas públicas da face da quadra, mas é o principal indicador oficial de microclima urbano e sombreamento das edificações.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (20, 'EPE_CONSUMO_RES_TOTAL_BA', 'Consumo Residencial de Energia Elétrica na Bahia', 'Consumo total anual de energia elétrica da classe residencial no estado da Bahia (soma das subclasses Convencional e Baixa Renda).', 'GWh', 'Energética', 'Dado observado', 'Estadual (UF - Bahia)', 2022, 'EPE Dados Abertos Anuário Estatístico: UF=''BA'', Setor=''Residencial'', Coluna ''Consumo'' (MWh / 1000)', 'Soma(Consumo_MWh_Mensal_BA) / 1000', 'Consolidação anual dos dados mensais de consumo residencial cativo na Bahia publicados pela EPE (série 2018-2025).', 'RESTRIÇÃO METODOLÓGICA ESTRITA: Indicador disponível apenas em escala estadual (UF Bahia). Nunca deve ser atribuído diretamente aos bairros como se fosse consumo local.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (21, 'EPE_PERC_CONSUMIDORES_BAIXA_RENDA_BA', 'Participação da Subclasse Residencial Baixa Renda (Tarifa Social) na Bahia', 'Percentual de unidades consumidoras residenciais da Bahia enquadradas na Tarifa Social de Energia Elétrica (Subclasse Baixa Renda).', '%', 'Energética', 'Indicador derivado', 'Estadual (UF - Bahia)', 2022, 'EPE Dados Abertos: Consumidores UF=''BA'', Setor N2=''Baixa Renda'' vs Total Residencial', '(Consumidores_Baixa_Renda_BA / Consumidores_Residenciais_Totais_BA) * 100', 'Razão entre a média anual de unidades consumidoras residenciais Baixa Renda e o total de unidades consumidoras residenciais na Bahia.', 'Escala estadual (UF Bahia). Contextualiza a importância estrutural da Tarifa Social na Bahia (28,22% em 2022, subindo para 32,78% em 2025), mas não informa a taxa de cobertura específica dentro de cada bairro soteropolitano.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (22, 'PROXY_RISCO_TERMICO_URBANO', 'Índice Proxy de Exposição ao Desconforto Térmico Urbano', 'Proxy que combina o déficit de arborização viária (faces sem árvores) e a intensidade de adensamento demográfico para estimar a propensão a ilhas de calor e demanda por climatização.', 'índice (0 a 100)', 'Socioenergética', 'Proxy/estimativa', 'Bairro / Município', 2022, 'IBGE Censo 2022: Déficit de Arborização (V05030/V05000) e Densidade Demográfica (V0001/AREA_KM2)', '0.60 * Perc_Sem_Arvores + 0.40 * Min(100, (Densidade_Hab_Km2 / 25000) * 100)', 'Combinação ponderada entre a ausência de sombreamento arbóreo na quadra (60%) e a compacidade construtiva/populacional relativa a 25.000 hab/km² (40%).', 'Trata-se de uma proxy ambiental/urbana: não mede a temperatura interna das edificações nem o padrão construtivo do telhado (fibrocimento/laje sem isolamento térmico).');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (23, 'PROXY_COMPROMETIMENTO_RENDA_ENERGIA', 'Proxy de Pressão Tarifária Potencial sobre a Renda Mediana', 'Estimativa exploratória do peso percentual de uma fatura elétrica residencial de referência estadual (consumo médio residencial da Bahia na tarifa convencional) sobre o rendimento mediano do responsável no território.', '% da renda mediana', 'Socioenergética', 'Proxy/estimativa', 'Bairro / Município (Cruzamento Multiescalar Contextual)', 2022, 'IBGE Censo 2022 (V06004, V06006, V0005) + Parâmetro Contextual EPE Bahia (Consumo médio ~110,1 kWh/mês ajustado pelo porte domiciliar)', '((Consumo_Ref_kWh * Tarifa_Media_Ref_R$_kWh * Fator_Pressao_Local) / Renda_Referencia_Local) * 100', 'Avalia a vulnerabilidade econômica ao custo da energia elétrica caso a família não usufrua integralmente do desconto da Tarifa Social (TSEE) ou sofra acréscimo de consumo por equipamentos ineficientes (geladeiras antigas/ventiladores em uso contínuo).', 'PROXY EXPLORATÓRIA: Como a EPE não divulga consumo por bairro e o Censo 2022 não coleta valor da conta de luz, este indicador estima a sensibilidade orçamentária a partir da renda local observada e de parâmetros médios estaduais, não comprovando pobreza energética individual.');
INSERT INTO indicadores (id, codigo, nome, descricao, unidade, dimensao, classificacao, escala_geografica, ano_referencia, variaveis_origem, formula, metodologia, limitacoes) VALUES (24, 'IEVS_EXPLORATORIO', 'Índice Exploratório de Vulnerabilidade Socioenergética (IEVS)', 'Índice sintético multidimensional proposto pelo projeto (Desafio Adicional) integrando Renda (40%), Habitação/Saneamento (30%) e Condições Urbanas/Térmicas (30%).', 'índice (0 a 100)', 'Socioenergética', 'Proxy/estimativa', 'Bairro / Setor Censitário / Município', 2022, 'Subíndices normalizados (0-100): Déficit de Renda (I_Renda), Vulnerabilidade Habitacional/Acesso (I_Hab) e Risco Urbano-Térmico (I_Urb)', 'IEVS = w_renda * I_Renda + w_hab * I_Hab + w_urb * I_Urb (Pesos base: 0.40, 0.30, 0.30)', 'Normalização min-max padronizada (0 = menor vulnerabilidade, 100 = maior vulnerabilidade) sobre variáveis oficiais do Censo 2022, acompanhada de teste de sensibilidade sob 4 cenários de pesos.', 'AVISO OBRIGATÓRIO: O IEVS é um instrumento analítico exploratório para priorização territorial e NÃO constitui índice oficial nem medida validada direta de pobreza energética domiciliar.');
