INSERT INTO analyses (id, questao_numero, titulo, dimensao_foco, descricao, data_criacao) VALUES (1, 1, '1. Qual é o perfil demográfico de Beiru/Tancredo Neves e Pernambués?', 'Demográfica', 'Segundo o Censo Demográfico 2022 (IBGE), Pernambués (código oficial 2927408117) possui 52.564 habitantes distribuídos em 3,2074 km² (densidade de 16.388,4 hab/km², 4,7x superior à média de Salvador de 3.486,5 hab/km²) e 27.278 domicílios totais (21.561 DPPO, média de 2,40 moradores/domicílio), sendo o 3º bairro em volume domiciliar da capital. Já Beiru / Tancredo Neves (código 2927408018) conta com 38.329 habitantes em apenas 1,6362 km², alcançando uma densidade demográfica extrema de 23.425,5 hab/km² (6,7x a média municipal e 42,9% mais denso que Pernambués), com 19.870 domicílios totais (15.454 DPPO e média de 2,50 moradores/domicílio). Demograficamente, Beiru/Tancredo Neves possui estrutura etária mais jovem (18,00% de 0-14 anos e razão de dependência de 49,24%, contra 15,81% e 44,61% em Pernambués) e maior proporção de população negra (91,42% pretos e pardos, sendo 41,62% pretos, face a 86,54% em Pernambués e 83,03% em Salvador). Nota metodológica fundamental: no recorte específico de ''Favelas e Comunidades Urbanas'' (FCU) do Censo 2022, Beiru/Tancredo Neves soma 38.871 moradores (10ª maior favela do Brasil e 1ª da Bahia) e Pernambués soma 35.110 moradores (11ª do Brasil e 2ª da Bahia), pois os limites das FCUs seguem a morfologia de ocupação subnormal e não coincidem milimetricamente com a poligonal administrativa da Lei Municipal nº 9.278/2017.', '2026-11-11');
INSERT INTO analyses (id, questao_numero, titulo, dimensao_foco, descricao, data_criacao) VALUES (2, 2, '2. Como se distribuem os indicadores de rendimento?', 'Econômica', 'Ambos os bairros apresentam forte restrição de renda em comparação à média de Salvador (R$ 3.160,73), mas com estruturas distributivas distintas. O rendimento nominal mediano do responsável pelo domicílio (V06006) é idêntico nos dois territórios: R$ 1.212,00 (exatamente 1 salário mínimo vigente em 2022), comprovando que em ambos os bairros pelo menos 50% dos chefes de família sobrevivem com até 1 salário mínimo. Contudo, o rendimento nominal médio (V06004) em Beiru/Tancredo Neves é de R$ 2.035,87 (35,6% abaixo da média municipal), enquanto em Pernambués atinge R$ 2.316,25 (13,8% superior ao Beiru e 26,7% abaixo de Salvador). A análise desagregada pelos 172 setores censitários explica essa diferença: em Beiru/Tancredo Neves a vulnerabilidade de renda é mais homogênea (85,92% dos setores válidos, 61/71, com rendimento médio ≤ 1,5 SM, ante 48,60% em Salvador), enquanto Pernambués apresenta forte desigualdade intrabairro (razão Média/Mediana de 1,91x contra 1,68x no Beiru), coexistindo 72 setores de baixa renda (72,00%) na comunidade tradicional (médias entre R$ 1.150 e R$ 1.500) com setores de condomínios verticalizados próximos à Av. Paralela e Horto Bela Vista (onde o rendimento médio supera R$ 4.500).', '2026-11-11');
INSERT INTO analyses (id, questao_numero, titulo, dimensao_foco, descricao, data_criacao) VALUES (3, 3, '3. Quais condições habitacionais podem representar vulnerabilidade?', 'Habitacional', 'Embora o acesso físico à rede geral de água seja quase universal (99,82% no Beiru e 99,74% em Pernambués) e a cobertura de rede de esgoto/pluvial supere 98%, quatro condições habitacionais revelam vulnerabilidade crítica: (1) Morfologia da coleta de resíduos sólidos: apenas 29,19% dos domicílios do Beiru/Tancredo Neves e 40,83% de Pernambués contam com coleta direta porta a porta (contra 57,26% em Salvador); a maioria depende de caçambas comunitárias (68,14% no Beiru e 54,61% em Pernambués), e em Pernambués 4,56% dos domicílios (983 moradias) não possuem coleta regular; (2) Saneamento precário residual em fundos de vale: 230 domicílios no Beiru (1,49%) e 135 em Pernambués (0,63%) ainda lançam esgoto em fossa rudimentar ou vala aberta; (3) Adensamento domiciliar elevado: 206 famílias no Beiru (1,33%) e 202 em Pernambués (0,94%) têm 6 ou mais moradores, elevando a demanda contínua por refrigeração de alimentos e banho; e (4) Predominância de edificações autoconstruídas (89,6% de casas no Beiru vs 77,9% em Pernambués), frequentemente em alvenaria sem reboco térmico ou lajes expostas.', '2026-11-11');
INSERT INTO analyses (id, questao_numero, titulo, dimensao_foco, descricao, data_criacao) VALUES (4, 4, '4. Quais diferenças existem na infraestrutura urbana?', 'Urbana', 'Os dados de Características Urbanísticas do Entorno do Censo 2022 revelam contrastes marcantes entre os dois bairros e a média soteropolitana: (1) Déficit severo de arborização viária: em Beiru/Tancredo Neves, 74,37% dos domicílios estão em faces de quadra sem nenhuma árvore (apenas 24,48% com arborização), situação substancialmente mais crítica que em Pernambués (34,02% com arborização e 65,07% sem árvores) e Salvador (34,51%); (2) Ausência de calçadas e acessibilidade crítica: ambos os bairros sofrem com a falta de passeio público (apenas 39,46% têm calçada no Beiru e 38,57% em Pernambués, ante 56,87% em Salvador), mas a acessibilidade por rampa para cadeirante é quase nula em Beiru/Tancredo Neves (0,73% contra 7,12% em Pernambués e 7,15% em Salvador), reflexo da topografia acidentada de cumeada e encostas sem urbanização padronizada; (3) Drenagem urbana (bueiros/bocas de lobo): presente em 60,92% das faces no Beiru e 68,88% em Pernambués; e (4) Iluminação pública: embora elevada, Beiru/Tancredo Neves apresenta cobertura inferior (96,51%, deixando 528 domicílios às escuras na face da quadra) em comparação a Pernambués (98,51%, com 320 domicílios sem iluminação).', '2026-11-11');
INSERT INTO analyses (id, questao_numero, titulo, dimensao_foco, descricao, data_criacao) VALUES (5, 5, '5. Quais indicadores permitem discutir riscos de vulnerabilidade energética?', 'Socioenergética', 'A vulnerabilidade energética multidimensional nos dois bairros emerge da interseção de quatro vetores críticos (consolidados no IEVS Base: 66,17 no Beiru vs 52,98 em Pernambués): (1) Rendimento mediano de 1 salário mínimo (R$ 1.212,00 em ambos) e alta concentração de setores de baixa renda (85,92% dos setores válidos do Beiru e 72,00% de Pernambués têm renda média ≤ 1,5 SM), indicando elevado comprometimento orçamentário com a fatura de energia elétrica e gás de cozinha (GLP); (2) Déficit de arborização (74,37% sem árvores no Beiru e 65,07% em Pernambués) somado à hiperdensidade demográfica (23.425,5 hab/km² no Beiru e 16.388,4 hab/km² em Pernambués), que intensifica ilhas de calor intraurbanas e exige uso prolongado de ventiladores e geladeiras em regime de esforço térmico; (3) Precariedade viária (baixa coleta direta e ausência de calçadas), que reflete becos estreitos onde a rede de distribuição de baixa tensão sofre com ligações informais, sobrecarga de transformadores e dificuldade de acesso para manutenção; e (4) Taxa de analfabetismo residual (4,96% no Beiru e 3,24% em Pernambués, totalizando 2.993 adultos), que cria barreiras burocráticas ao cadastramento na Tarifa Social de Energia Elétrica (TSEE).', '2026-11-11');
INSERT INTO analyses (id, questao_numero, titulo, dimensao_foco, descricao, data_criacao) VALUES (6, 6, '6. Como os dados energéticos da Bahia contextualizam os territórios?', 'Energética', 'A série histórica oficial da EPE para a Bahia (2018-2025) mostra que o consumo residencial estadual cresceu de 7.039,93 GWh (2018) para 7.555,35 GWh no ano censitário de 2022, atingiu 8.162,02 GWh em 2024 (+15,9%) e fechou em 8.048,81 GWh em 2025, enquanto o número de unidades consumidoras residenciais avançou de 5,25 milhões (2018) para 5,72 milhões (2022) e 6,16 milhões (2025). O dado estrutural mais relevante extraído dos microdados abertos da EPE é o peso da Subclasse Residencial Baixa Renda (Tarifa Social - TSEE) na Bahia: em 2022, 1.613.851 famílias baianas (28,22% de todos os consumidores residenciais do estado) estavam enquadradas na Baixa Renda, consumindo 2.102,72 GWh (média de 108,58 kWh/mês por unidade, muito próxima aos 110,68 kWh/mês da classe convencional). Em 2025, a subclasse Baixa Renda atingiu 2.020.262 unidades consumidoras (32,78% do estado). Esse contexto estadual demonstra que quase um terço dos domicílios baianos depende de subsídio tarifário para manter um patamar básico de consumo (~109-110 kWh/mês), sendo Beiru/Tancredo Neves e Pernambués territórios prioritários em Salvador para busca ativa do CadÚnico/TSEE devido à sua mediana salarial de 1 SM.', '2026-11-11');
INSERT INTO analyses (id, questao_numero, titulo, dimensao_foco, descricao, data_criacao) VALUES (7, 7, '7. Que informações adicionais seriam necessárias para medir vulnerabilidade energética familiar diretamente?', 'Socioenergética', 'Como baixa renda não comprova automaticamente pobreza energética familiar e iluminação pública não mede a qualidade do fornecimento domiciliar, para medir a vulnerabilidade energética diretamente na escala familiar e intrabairro seriam necessários: (1) Dados operacionais da distribuidora local (Neoenergia Coelba) desagregados por conjunto elétrico/alimentador e CEP: indicadores de continuidade DEC (Duração Equivalente de Interrupção por Unidade Consumidora) e FEC (Frequência Equivalente de Interrupção), nível de tensão em regime permanente e índice de perdas não técnicas; (2) Dados comerciais anonimizados por bairro: percentual efetivo de domicílios beneficiários da Tarifa Social (TSEE) frente ao total elegível no CadÚnico (hiato de cobertura), taxa de inadimplência e cortes de fornecimento por falta de pagamento; (3) Pesquisa de Posse e Hábitos de Uso de Equipamentos (PPH) local: idade e selo Procel do parque de eletrodomésticos (especialmente refrigeradores e condicionadores de ar), uso de lenha/carvão/GLP para cocção; e (4) Auditoria termográfica e construtiva das moradias: medição de temperatura interna diurna/noturna, presença de telhados de fibrocimento sem forro e ventilação cruzada.', '2026-11-11');
INSERT INTO analyses (id, questao_numero, titulo, dimensao_foco, descricao, data_criacao) VALUES (8, 8, '8. Que intervenções poderiam ser priorizadas, considerando evidências e limitações?', 'Socioenergética', 'Com base nas evidências empíricas do Censo 2022, IPEA e EPE, recomenda-se um plano integrado em 4 eixos prioritários: (1) Eficiência Energética e Busca Ativa da Tarifa Social (Prioridade Máxima em ambos os bairros, com foco nos 61 setores (85,92%) de baixa renda do Beiru/Tancredo Neves e nos 72 setores (72,00%) de Pernambués): mutirões de recadastramento automático no CadÚnico/TSEE articulados aos CRAS locais e ampliação dos programas de Eficiência Energética da ANEEL/Coelba para substituição gratuita de geladeiras antigas e lâmpadas por LED; (2) Arborização Urbana e Mitigação de Ilhas de Calor (Prioridade Crítica em Beiru/Tancredo Neves, onde 74,37% das faces não têm árvores e a densidade chega a 23.425 hab/km²): plantio de espécies arbóreas de porte compatível com redes elétricas compactas, implantação de telhados frios/pintura reflexiva em lajes comunitárias e criação de microparques de sombreamento; (3) Geração Distribuída Comunitária (Solar Social): instalação de sistemas fotovoltaicos em equipamentos públicos (escolas, postos de saúde e sedes comunitárias) com compensação de créditos para famílias vulneráveis; e (4) Qualificação Urbana e Acessibilidade: requalificação de calçadas e rampas (especialmente no Beiru, hoje com apenas 0,73% de acessibilidade) acoplada à modernização da rede elétrica secundária em becos e travessas.', '2026-11-11');
